# qx_levenshtein :: ('kitten', 'sitting')
def qx_levenshtein(a, b):
    m, n = len(a), len(b)
    if m < n: a, b = b, a; m, n = n, m
    prev = list(range(n + 1))
    for i, ca in enumerate(a, 1):
        curr = [i] + [0] * n
        for j, cb in enumerate(b, 1):
            curr[j] = min(curr[j-1] + 1, prev[j] + 1, prev[j-1] + (ca != cb))
        prev = curr
    return prev[n]

if __name__ == '__main__':
    print(qx_levenshtein(('kitten', 'sitting')))

